import{_ as i,o as e,c as a,a5 as o}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ39 判断两个IP是否属于同一子网","description":"较难 通过率：18.16% 时间限制：1秒 空间限制：32M 知识点 字符串 模拟 描述 IP地址是由4个0 255之间的整数构成的，用\\".\\"符号相连。 二进制的IP地址格式有32位，例如：10000011，01101011，00000011，00011000;每八位用十进制表示。","frontmatter":{"title":"HJ39 判断两个IP是否属于同一子网","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"较难 通过率：18.16% 时间限制：1秒 空间限制：32M 知识点 字符串 模拟 描述 IP地址是由4个0 255之间的整数构成的，用\\".\\"符号相连。 二进制的IP地址格式有32位，例如：10000011，01101011，00000011，00011000;每八位用十进制表示。","sidebarWeight":90,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为较难题/HJ39 判断两个IP是否属于同一子网.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为较难题/HJ39 判断两个IP是否属于同一子网.md","filePath":"posts/前端面试与实战/03-算法训练/华为较难题/HJ39 判断两个IP是否属于同一子网.md"}'),n={name:"posts/前端面试与实战/03-算法训练/华为较难题/HJ39 判断两个IP是否属于同一子网.md"};function p(r,t,s,l,_,d){return e(),a("div",null,[...t[0]||(t[0]=[o('<div><h1 id="hj39-判断两个ip是否属于同一子网" tabindex="-1">HJ39 判断两个IP是否属于同一子网 <a class="header-anchor" href="#hj39-判断两个ip是否属于同一子网" aria-label="Permalink to &quot;HJ39 判断两个IP是否属于同一子网&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ39 判断两个IP是否属于同一子网”的核心思路，并能把它用于实际开发或面试表达。 较难 通过率：18.16% 时间限制：1秒 空间限制：32M 知识点==字符串====模拟== <strong>描述</strong> IP地址是由4个0-255之间的整数构成的，用&quot;.&quot;符号相连。 二进制的IP地址格式有32位，例如：10000011，01101011，00000011，00011000;每八位用十进制表示就是131.107.3.24 子网掩码是用来判断任意两台计算机的IP地址是否属于同一子网络的根据。 子网掩码与IP地址结构相同，是32位二进制数，由1和0组成，且1和0分别连续，其中网络号部分全为“1”和主机号部分全为“0”。 你可以简单的认为子网掩码是一串连续的1和一串连续的0拼接而成的32位二进制数，左边部分都是1，右边部分都是0。 利用子网掩码可以判断两台主机是否在同一子网中。 若两台主机的IP地址分别与它们的子网掩码进行逻辑“与”运算（按位与/AND）后的结果相同，则说明这两台主机在同一子网中。</p></blockquote><p>示例： I P 地址　 192.168.0.1 子网掩码　 255.255.255.0 转化为二进制进行运算： I P 地址　 11000000.10101000.00000000.00000001 子网掩码　11111111.11111111.11111111.00000000 AND运算 11000000.10101000.00000000.00000000 转化为十进制后为： 192.168.0.0</p><p>I P 地址　 192.168.0.254 子网掩码　 255.255.255.0</p><p>转化为二进制进行运算： I P 地址　11000000.10101000.00000000.11111110 子网掩码 11111111.11111111.11111111.00000000 AND运算 11000000.10101000.00000000.00000000 转化为十进制后为： 192.168.0.0 通过以上对两台计算机IP地址与子网掩码的AND运算后，我们可以看到它运算结果是一样的。均为192.168.0.0，所以这二台计算机可视为是同一子网络。</p><p>输入一个子网掩码以及两个ip地址，判断这两个ip地址是否是一个子网络。 若IP地址或子网掩码格式非法则输出1，若IP1与IP2属于同一子网络输出0，若IP1与IP2不属于同一子网络输出2。</p><p>注: 有效掩码与IP的性质为：</p><ol><li>掩码与IP每一段在 0 - 255 之间</li><li>掩码的二进制字符串前缀为网络号，都由‘1’组成；后缀为主机号，都由&#39;0&#39;组成 <strong>输入描述：</strong> 3行输入，第1行是输入子网掩码、第2，3行是输入两个ip地址 题目的示例中给出了三组数据，但是在实际提交时，你的程序可以只处理一组数据（3行）。 <strong>输出描述：</strong> 若IP地址或子网掩码格式非法则输出1，若IP1与IP2属于同一子网络输出0，若IP1与IP2不属于同一子网络输出2 <strong>示例1</strong> 输入： 255.255.255.0192.168.224.256192.168.10.4 255.0.0.0193.194.202.15232.43.7.59 255.255.255.0192.168.0.254192.168.0.1</li></ol><p>输出： 120</p><p>说明： 对于第一个例子:255.255.255.0192.168.224.256192.168.10.4其中IP:192.168.224.256不合法，输出1</p><p>对于第二个例子:255.0.0.0193.194.202.15232.43.7.592个与运算之后，不在同一个子网，输出2</p><p>对于第三个例子，2个与运算之后，如题目描述所示，在同一个子网，输出0</p><ul><li>{:08b}是一个格式说明符。:引入格式说明符，08表示结果字符串应该有8个字符宽，不足部分用0填充（这就是确保前导零的部分），b表示二进制格式。</li><li>.format(int(i))是将int(i)（i字符串的整数形式）格式化为上述说明符指定的格式的方法。对于列表intList中的每个元素i，都将执行这个操作。</li><li>[&quot;{:08b}&quot;.format(int(i)) for i in intList]是一个列表推导式，它遍历intList，将每个元素转换为8位的二进制字符串，然后这些字符串被组成一个列表。</li><li>&quot;.join([...])`方法将前面步骤生成的列表中的所有字符串连接成一个单一的字符串，其中每个部分之间没有任何分隔符。</li></ul><p><strong>&#39;{:8b}&#39;和&#39;{:08b}&#39;有什么区别</strong> 在Python的字符串格式化中，<code>{:8b}</code>和<code>{:08b}</code>都用于将整数格式化为二进制字符串，但它们在处理前导零方面有所不同：</p><ul><li><p><code>{:8b}</code>：这个格式说明符表示转换成的二进制字符串至少占用8位宽度。如果转换后的二进制数位数少于8位，它将使用空格填充剩余的位数，直到总宽度达到8位。这意味着，如果你转换的数字较小，导致二进制表示不足8位，那么结果字符串的前面将会用空格填充。</p></li><li><p><code>{:08b}</code>：这个格式说明符同样表示转换成的二进制字符串至少占用8位宽度，但与上一个不同的是，如果二进制数位数少于8位，它将使用0而不是空格来填充剩余的位数，直到总宽度达到8位。这种方式确保了二进制字符串总是8位长，对于需要固定长度的二进制数据表示，如IP地址的每一段，这是非常有用的。</p></li></ul><h3 id="举例说明" tabindex="-1">举例说明 <a class="header-anchor" href="#举例说明" aria-label="Permalink to &quot;举例说明&quot;">​</a></h3><p>假设我们要格式化数字<code>5</code>为二进制字符串：</p><ul><li>使用<code>{:8b}</code>格式化，得到的结果可能是<code>&#39; 101&#39;</code>（前面有5个空格）。</li><li>使用<code>{:08b}</code>格式化，得到的结果是<code>&#39;00000101&#39;</code>。</li></ul><p>对于网络编程和处理需要固定长度二进制表示的场合，如IP地址处理，<code>{:08b}</code>是更合适的选择，因为它保证了二进制字符串的长度，易于后续的处理和计算。</p><p>def check_ip_or_mask(parts):</p><h1 id="检查ip地址或子网掩码的每个部分是否在0到255之间" tabindex="-1">检查IP地址或子网掩码的每个部分是否在0到255之间 <a class="header-anchor" href="#检查ip地址或子网掩码的每个部分是否在0到255之间" aria-label="Permalink to &quot;检查IP地址或子网掩码的每个部分是否在0到255之间&quot;">​</a></h1><p>return all(0 &lt;= int(p) &lt;= 255 for p in parts)</p><p>def is_valid_mask(mask):</p><h1 id="将子网掩码转换为二进制字符串" tabindex="-1">将子网掩码转换为二进制字符串 <a class="header-anchor" href="#将子网掩码转换为二进制字符串" aria-label="Permalink to &quot;将子网掩码转换为二进制字符串&quot;">​</a></h1><p>bin_mask = &#39;&#39;.join([&#39;{:08b}&#39;.format(int(part)) for part in mask])</p><h1 id="找到第一个0出现的位置" tabindex="-1">找到第一个0出现的位置 <a class="header-anchor" href="#找到第一个0出现的位置" aria-label="Permalink to &quot;找到第一个0出现的位置&quot;">​</a></h1><p>first_zero_index = bin_mask.find(&#39;0&#39;)</p><h1 id="确保从第一个0之后不再出现1" tabindex="-1">确保从第一个0之后不再出现1 <a class="header-anchor" href="#确保从第一个0之后不再出现1" aria-label="Permalink to &quot;确保从第一个0之后不再出现1&quot;">​</a></h1><p>return &#39;1&#39; not in bin_mask[first_zero_index:]</p><p>while True: try: mask = input().split(&quot;.&quot;) ip1 = input().split(&quot;.&quot;) ip2 = input().split(&quot;.&quot;) if not (check_ip_or_mask(mask) and check_ip_or_mask(ip1) and check_ip_or_mask(ip2) and is_valid_mask(mask)): print(&quot;1&quot;) continue def get_bin(intList): return &quot;&quot;.join([&quot;{:08b}&quot;.format(int(i)) for i in intList]) def is_same_net(mask, ip1, ip2): bin_mask = int(get_bin(mask), 2) p1_net = int(get_bin(ip1), 2) &amp; bin_mask p2_net = int(get_bin(ip2), 2) &amp; bin_mask print(0 if p1_net == p2_net else 2) is_same_net(mask, ip1, ip2) except EOFError: break</p></div>',1)])])}const P=i(n,[["render",p]]);export{u as __pageData,P as default};
